sig Order { id: Int, amount: Int, state: one State }
abstract sig State {}
one sig Initial extends State {}
one sig Failed extends State {}
fact PositiveAmount { all o: Order | o.amount > 0 }

sig Order { id: Int, customerId: Int, state: one State }
abstract sig State {}
fact NonEmptyCustomer { all o: Order | o.customerId != none }

abstract sig State {}
one sig Pending extends State {}
one sig Paid extends State {}
one sig Shipped extends State {}
one sig Completed extends State {}
pred transition[t, t': Time] { all o: Order | o.state = Pending and o.state' = Paid or o.state = Paid and o.state' = Shipped or o.state = Shipped and o.state' = Completed }

abstract sig State {}
one sig Pending extends State {}
one sig Paid extends State {}
pred pay { all o: Order | o.state = Pending implies o.state' = Paid }

abstract sig State {}
one sig Pending extends State {}
one sig Paid extends State {}
pred refund { all o: Order | o.state = Paid implies o.state' = Pending }

abstract sig State {}
one sig Pending extends State {}
one sig Cancelled extends State {}
pred cancel { all o: Order | o.state = Pending implies o.state' = Cancelled }

abstract sig State {}
one sig Pending extends State {}
one sig Paid extends State {}
one sig Shipped extends State {}
one sig Completed extends State {}
fact Invariants { all o: Order | one o.state }

sig Notification { userId: Int, channel: Channel, content: String }
abstract sig Channel {}
one sig SMS extends Channel {}
one sig EMAIL extends Channel {}
one sig PUSH extends Channel {}
fact Validate { all n: Notification | n.channel in (SMS + EMAIL + PUSH) }

abstract sig DeliveryStatus {}
one sig Success extends DeliveryStatus {}
one sig Failed extends DeliveryStatus {}
one sig Timeout extends DeliveryStatus {}
sig Notification { status: one DeliveryStatus }
fact ValidStatus { all n: Notification | n.status in (Success + Failed + Timeout) }

sig Blacklist { userId: Int }
sig Notification { userId: Int }
fact NoBlacklist { all n: Notification | n.userId !in Blacklist.userId }

abstract sig Channel {}
one sig SMS extends Channel {}
one sig EMAIL extends Channel {}
one sig PUSH extends Channel {}
sig Notification { channel: one Channel }
fact ChannelDist { all n: Notification | n.channel in (SMS + EMAIL + PUSH) }

sig Notification { userId: Int, channel: Channel, content: String }
abstract sig Channel {}
one sig SMS extends Channel {}
fact HasChannel { all n: Notification | n.channel in Channel }

sig Exam { id: Int, title: String, duration: Int, passingScore: Int, status: one ExamStatus }
abstract sig ExamStatus {}
one sig Unpublished extends ExamStatus {}
one sig Published extends ExamStatus {}
fact ValidExam { all e: Exam | e.duration > 0 and e.passingScore >= 0 }

sig Question { id: Int, type: one QuestionType }
abstract sig QuestionType {}
one sig SingleChoice extends QuestionType {}
one sig MultiChoice extends QuestionType {}
one sig TrueFalse extends QuestionType {}
one sig Essay extends QuestionType {}

sig Question { difficulty: one Difficulty }
abstract sig Difficulty {}
one sig Easy extends Difficulty {}
one sig Medium extends Difficulty {}
one sig Hard extends Difficulty {}
fact ValidDifficulty { all q: Question | q.difficulty in (Easy + Medium + Hard) }

sig Appeal { studentId: Int, status: one AppealStatus }
abstract sig AppealStatus {}
one sig Pending extends AppealStatus {}
one sig Reviewed extends AppealStatus {}
